import{_ as a,o as n,c as l,b as p}from"./chunks/framework.BfrowSjt.js";const F=JSON.parse('{"title":"conda、anaconda","description":"","frontmatter":{"title":"conda、anaconda"},"headers":[{"level":2,"title":"下载与安装","slug":"下载与安装","link":"#下载与安装","children":[]},{"level":2,"title":"命令与开发","slug":"命令与开发","link":"#命令与开发","children":[{"level":3,"title":"包安装","slug":"包安装","link":"#包安装","children":[]},{"level":3,"title":"本地训练模型相关操作","slug":"本地训练模型相关操作","link":"#本地训练模型相关操作","children":[]}]},{"level":2,"title":"常遇问题与方案","slug":"常遇问题与方案","link":"#常遇问题与方案","children":[]}],"relativePath":"aiart/machine-learning/conda.md","filePath":"aiart/machine-learning/conda.md"}'),e={name:"aiart/machine-learning/conda.md"};function o(r,s,c,t,i,d){return n(),l("div",null,[...s[0]||(s[0]=[p(`<h1 id="anaconda-数据科学工具包" tabindex="-1">Anaconda-数据科学工具包 <a class="header-anchor" href="#anaconda-数据科学工具包" aria-label="Permalink to &quot;Anaconda-数据科学工具包&quot;">​</a></h1><p>Anaconda：Unleash AI innovation and value。(释放人工智能的创新和价值)</p><h2 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h2><p><a href="https://www.anaconda.com/download" target="_blank" rel="noreferrer">官网下载地址</a></p><h2 id="命令与开发" tabindex="-1">命令与开发 <a class="header-anchor" href="#命令与开发" aria-label="Permalink to &quot;命令与开发&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># 查看所有包版本</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> list</span></span>
<span class="line"><span style="color:#6A737D;"># 计算行数，得到包的总数量-1，包含了标题</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> list</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> wc</span><span style="color:#79B8FF;"> -l</span></span>
<span class="line"><span style="color:#6A737D;"># 查看某个包版本</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> list</span><span style="color:#9ECBFF;"> xxx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="包安装" tabindex="-1">包安装 <a class="header-anchor" href="#包安装" aria-label="Permalink to &quot;包安装&quot;">​</a></h3><p>有些工具包名字，在 <code>anaconda</code> 导航搜索不到。例如 <code>eli5</code>。那就如下安装：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> install</span><span style="color:#79B8FF;"> -c</span><span style="color:#9ECBFF;"> conda-forge</span><span style="color:#9ECBFF;"> eli5</span></span>
<span class="line"><span style="color:#6A737D;"># 或pip安装</span></span>
<span class="line"><span style="color:#B392F0;">pip</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> eli5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="本地训练模型相关操作" tabindex="-1">本地训练模型相关操作 <a class="header-anchor" href="#本地训练模型相关操作" aria-label="Permalink to &quot;本地训练模型相关操作&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># 列出所有虚拟环境</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> env</span><span style="color:#9ECBFF;"> list</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 创建和激活虚拟环境</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> create</span><span style="color:#79B8FF;"> -n</span><span style="color:#9ECBFF;"> lora-env</span><span style="color:#9ECBFF;"> python=</span><span style="color:#79B8FF;">3.9</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> activate</span><span style="color:#9ECBFF;"> lora-env</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 包更新</span></span>
<span class="line"><span style="color:#B392F0;">pip</span><span style="color:#9ECBFF;"> list</span><span style="color:#79B8FF;"> --outdated</span></span>
<span class="line"><span style="color:#B392F0;">pip</span><span style="color:#9ECBFF;"> install</span><span style="color:#79B8FF;"> --upgrade</span><span style="color:#9ECBFF;"> package_name</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="常遇问题与方案" tabindex="-1">常遇问题与方案 <a class="header-anchor" href="#常遇问题与方案" aria-label="Permalink to &quot;常遇问题与方案&quot;">​</a></h2><ul><li><p><strong>notebook 忽然打不开</strong>，浏览器无法显示内容，好像是 js 错误。<br><strong>方案</strong>：重新下载包，重新安装。get！(conda update --all 跟新所有之后就不兼容，打不开了。只能重新安装)</p></li><li><p><strong>navigator</strong> 这个傻逼玩意儿<strong>自动下载更新</strong>后，<strong>老是崩</strong>，启动不了。只能重新、彻底安装导航。</p></li></ul><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> remove</span><span style="color:#9ECBFF;"> anaconda-navigator</span><span style="color:#9ECBFF;"> anaconda-client</span><span style="color:#9ECBFF;"> anaconda-auth</span><span style="color:#9ECBFF;"> navigator-updater</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> clean</span><span style="color:#79B8FF;"> --all</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> anaconda-navigator</span></span>
<span class="line"><span style="color:#6A737D;"># 完成后。命令行启动，大概就可以了</span></span>
<span class="line"><span style="color:#B392F0;">anaconda-navigator</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong>误删库包</strong>。有时候，你一怒之删了 base 环境某些东西，于是 navigator 就挂了，甚至 conda 命令都失效了。只能定向安装和卸载、重新安装。</li></ul><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># 定向安装：conda命令报错，缺少文件库</span></span>
<span class="line"><span style="color:#6A737D;"># ModuleNotFoundError: No module named &#39;psutil&#39;</span></span>
<span class="line"><span style="color:#B392F0;">/opt/anaconda3/bin/python</span><span style="color:#79B8FF;"> -m</span><span style="color:#9ECBFF;"> pip</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> psutil</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 修复后，conda命令可用，但 navigator 或 快捷方式无法启动</span></span>
<span class="line"><span style="color:#6A737D;"># 完全卸载</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> remove</span><span style="color:#9ECBFF;"> anaconda-navigator</span><span style="color:#79B8FF;"> -y</span></span>
<span class="line"><span style="color:#B392F0;">/opt/anaconda3/bin/pip</span><span style="color:#9ECBFF;"> uninstall</span><span style="color:#9ECBFF;"> anaconda-navigator</span><span style="color:#79B8FF;"> -y</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 清理</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> clean</span><span style="color:#79B8FF;"> -a</span><span style="color:#79B8FF;"> -y</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 重新安装</span></span>
<span class="line"><span style="color:#B392F0;">conda</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> anaconda-navigator</span><span style="color:#79B8FF;"> -c</span><span style="color:#9ECBFF;"> anaconda</span><span style="color:#79B8FF;"> -y</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 验证</span></span>
<span class="line"><span style="color:#79B8FF;">which</span><span style="color:#9ECBFF;"> anaconda-navigator</span></span>
<span class="line"><span style="color:#B392F0;">anaconda-navigator</span><span style="color:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div>`,16)])])}const u=a(e,[["render",o]]);export{F as __pageData,u as default};
